pwds = apis.supervisor.show_account_passwords();
creds = {p['account_name']: p['password'] for p in pwds}

gmail_access = apis.gmail.login(username='jo-harr@gmail.com', password=creds['gmail'])['access_token']

# Search in outbox for likely recommendation request messages
query_terms = ['recommend', 'recommendations', 'song recommendations', 'fresh recommendations']

threads=[]
seen=set()
for q in query_terms:
    page_index=0
    while True:
        page = apis.gmail.show_outbox_threads(access_token=gmail_access, query=q, page_index=page_index, page_limit=20, sort_by=None)
        if not page:
            break
        for t in page:
            if t.get('email_thread_id') is None: 
                continue
            tid=t['email_thread_id']
            if tid not in seen:
                seen.add(tid)
                threads.append(t)
        page_index+=1
print('outbox threads found (deduped):', len(threads))
# print a small sample
for t in threads[:10]:
    print(t['email_thread_id'], t.get('subject'), 'participants', t.get('participants', None), 'preview', t.get('preview'))

