def parse_artists_from_text(body):
    if not body:
        return []
    lower=body.lower()
    if 'favorite artists' in lower:
        idx=lower.find('favorite artists')
        tail=body[idx+len('favorite artists'):]
    elif 'favorite artist' in lower:
        idx=lower.find('favorite artist')
        tail=body[idx+len('favorite artist'):]
    else:
