    tail=tail.strip()
    tail=tail.split('\n')[0]
    tail=tail.split('.')[0]
    tail=re.sub(r'[!?.]+$','',tail).strip()
    parts=[p.strip() for p in re.split(r',', tail) if p.strip()]
    return parts


def parse_artists_from_outbox_body(body):
    if not body:
        return []
    m=re.search(r"favorites?\s+artists\s*,\s*(.+)$", body, flags=re.IGNORECASE|re.DOTALL)
    if not m:
        # also allow "favorite artists" typo
        m=re.search(r"favorite\s+artists\s*,\s*(.+)$", body, flags=re.IGNORECASE|re.DOTALL)
    if not m:
        return []
    tail=m.group(1).strip()
    tail=tail.split('\n')[0]
    tail=tail.split('.')[0]
    tail=re.sub(r'[!?.]+$','',tail).strip()
    return [p.strip() for p in re.split(r',', tail) if p.strip()]

